    if (s[i] === "-") sign = -1;
    i++;
  }
  const limit = sign === 1 ? 2147483647 : 2147483648;
  let value = 0;
  while (i < n && s[i] >= "0" && s[i] <= "9") {
    const digit = s.charCodeAt(i) - 48;
